// Create Role Hierarchy for Testing
UserRole ceoRole;
UserRole vpRole;
UserRole mgrRole;
UserRole repRole;

// Check if roles already exist
List<UserRole> existingRoles = [SELECT Id, Name, DeveloperName FROM UserRole WHERE DeveloperName LIKE 'Flowstral_Test%'];
if(existingRoles.isEmpty()) {
    // CEO Role (top level)
    ceoRole = new UserRole(Name = 'Flowstral Test CEO', DeveloperName = 'Flowstral_Test_CEO');
    insert ceoRole;

    // VP Role (reports to CEO)
    vpRole = new UserRole(Name = 'Flowstral Test VP Sales', DeveloperName = 'Flowstral_Test_VP_Sales', ParentRoleId = ceoRole.Id);
    insert vpRole;

    // Manager Role (reports to VP)
    mgrRole = new UserRole(Name = 'Flowstral Test Sales Manager', DeveloperName = 'Flowstral_Test_Sales_Manager', ParentRoleId = vpRole.Id);
    insert mgrRole;

    // Rep Role (reports to Manager)
    repRole = new UserRole(Name = 'Flowstral Test Sales Rep', DeveloperName = 'Flowstral_Test_Sales_Rep', ParentRoleId = mgrRole.Id);
    insert repRole;

    System.debug('Created 4 test roles in hierarchy');
} else {
    System.debug('Test roles already exist: ' + existingRoles.size());
}

// Create Permission Sets for Testing
List<PermissionSet> existingPS = [SELECT Id, Name FROM PermissionSet WHERE Name LIKE 'Flowstral_Test%'];
if(existingPS.isEmpty()) {
    List<PermissionSet> newPS = new List<PermissionSet>();

    // Read Only Permission Set
    newPS.add(new PermissionSet(
        Name = 'Flowstral_Test_Read_Only',
        Label = 'Flowstral Test - Read Only',
        Description = 'Read-only access for testing'
    ));

    // Edit Permission Set
    newPS.add(new PermissionSet(
        Name = 'Flowstral_Test_Edit_Access',
        Label = 'Flowstral Test - Edit Access',
        Description = 'Edit access for testing'
    ));

    // Delete Permission Set
    newPS.add(new PermissionSet(
        Name = 'Flowstral_Test_Delete_Access',
        Label = 'Flowstral Test - Delete Access',
        Description = 'Delete access for testing'
    ));

    // API Access Permission Set
    newPS.add(new PermissionSet(
        Name = 'Flowstral_Test_API_Access',
        Label = 'Flowstral Test - API Access',
        Description = 'API enabled access for testing'
    ));

    insert newPS;
    System.debug('Created ' + newPS.size() + ' permission sets');
} else {
    System.debug('Permission sets already exist: ' + existingPS.size());
}

// Create Permission Set Group
List<PermissionSetGroup> existingPSG = [SELECT Id, DeveloperName FROM PermissionSetGroup WHERE DeveloperName = 'Flowstral_Test_Full_Access'];
if(existingPSG.isEmpty()) {
    PermissionSetGroup psg = new PermissionSetGroup(
        DeveloperName = 'Flowstral_Test_Full_Access',
        MasterLabel = 'Flowstral Test - Full Access Group',
        Description = 'Combines all Flowstral test permission sets'
    );
    insert psg;

    // Get the permission sets to add to group
    List<PermissionSet> testPS = [SELECT Id FROM PermissionSet WHERE Name LIKE 'Flowstral_Test%'];
    List<PermissionSetGroupComponent> components = new List<PermissionSetGroupComponent>();
    for(PermissionSet ps : testPS) {
        components.add(new PermissionSetGroupComponent(
            PermissionSetGroupId = psg.Id,
            PermissionSetId = ps.Id
        ));
    }
    if(!components.isEmpty()) {
        insert components;
    }
    System.debug('Created permission set group with ' + components.size() + ' components');
} else {
    System.debug('Permission set group already exists');
}

// Create Test Users with Different Profiles
// First, get profile IDs
Map<String, Id> profileMap = new Map<String, Id>();
for(Profile p : [SELECT Id, Name FROM Profile WHERE Name IN ('System Administrator', 'Standard User', 'Read Only', 'Chatter Free User', 'Marketing User')]) {
    profileMap.put(p.Name, p.Id);
}

// Check existing users
List<User> existingUsers = [SELECT Id, Username FROM User WHERE Username LIKE '%flowstral.test%'];
if(existingUsers.isEmpty()) {
    String orgId = UserInfo.getOrganizationId();
    String dateString = String.valueOf(Datetime.now()).replace(' ', '').replace(':', '').replace('-', '');

    List<User> newUsers = new List<User>();

    // Get roles
    Map<String, Id> roleMap = new Map<String, Id>();
    for(UserRole r : [SELECT Id, DeveloperName FROM UserRole WHERE DeveloperName LIKE 'Flowstral_Test%']) {
        roleMap.put(r.DeveloperName, r.Id);
    }

    // System Admin User
    if(profileMap.containsKey('System Administrator')) {
        newUsers.add(new User(
            FirstName = 'Test',
            LastName = 'Admin',
            Email = 'admin@flowstral.test',
            Username = 'admin@flowstral.test.' + orgId,
            Alias = 'tadmin',
