        ));
    }

    if(!newUsers.isEmpty()) {
        insert newUsers;
        System.debug('Created ' + newUsers.size() + ' test users');
    }
} else {
    System.debug('Test users already exist: ' + existingUsers.size());
}

// Assign Permission Sets to Test Users
List<User> testUsers = [SELECT Id, Username, Profile.Name FROM User WHERE Username LIKE '%flowstral.test%' AND IsActive = true];
List<PermissionSet> testPS = [SELECT Id, Name FROM PermissionSet WHERE Name LIKE 'Flowstral_Test%'];

if(!testUsers.isEmpty() && !testPS.isEmpty()) {
    // Check existing assignments
    Set<String> existingAssignments = new Set<String>();
    for(PermissionSetAssignment psa : [SELECT AssigneeId, PermissionSetId FROM PermissionSetAssignment WHERE AssigneeId IN :testUsers]) {
        existingAssignments.add(psa.AssigneeId + '-' + psa.PermissionSetId);
    }

    List<PermissionSetAssignment> newAssignments = new List<PermissionSetAssignment>();

    // Assign all permission sets to Standard user for testing
    for(User u : testUsers) {
        if(u.Username.contains('standard@')) {
            for(PermissionSet ps : testPS) {
                String key = u.Id + '-' + ps.Id;
                if(!existingAssignments.contains(key)) {
                    newAssignments.add(new PermissionSetAssignment(
                        AssigneeId = u.Id,
                        PermissionSetId = ps.Id
                    ));
                }
            }
        }
        // Assign Read Only PS to ReadOnly user
        if(u.Username.contains('readonly@')) {
            for(PermissionSet ps : testPS) {
                if(ps.Name.contains('Read_Only')) {
                    String key = u.Id + '-' + ps.Id;
                    if(!existingAssignments.contains(key)) {
                        newAssignments.add(new PermissionSetAssignment(
                            AssigneeId = u.Id,
                            PermissionSetId = ps.Id
                        ));
                    }
                }
            }
        }
    }

    if(!newAssignments.isEmpty()) {
        insert newAssignments;
        System.debug('Created ' + newAssignments.size() + ' permission set assignments');
    } else {
        System.debug('All assignments already exist');
    }
}
